//! The mint gate's canary LIBRARY: a crate EXTERNAL to the canary binary, whose macro draws
//! randomness when the binary invokes it. Clippy must report the draw at the invocation (or the
//! expanded-source scan must see it): a draw generated by another crate's macro is not hidden.

#[doc(hidden)]
pub mod reexport {
    pub use rand;
}

/// Fills `$buf` from the OS random number generator, written as an external crate's macro writes
/// it: through `$crate`.
#[macro_export]
macro_rules! external_draw {
    ($buf:expr) => {
        $crate::reexport::rand::RngCore::fill_bytes(&mut $crate::reexport::rand::rngs::OsRng, $buf)
    };
}
